    id: "cs-2020-hl-q13-b-ii", topicId: "cs-2-3", conceptId: "step-through-how-binary-search-algorithm",
    section: "B", questionRef: "2020 HL Q13(b)(ii)",
    stem: "Binary search is generally regarded as a highly efficient search algorithm. In his book The Art of Computer Programming, Donald Knuth states that “searching is the most time‐consuming part of many programs, and the substitution of a good search method for a bad one often leads to a substantial increase in speed.”",
    questionText: "Step through how the binary search algorithm finds the integer 28 in the list L shown below.",
    tariffModel: {"kind":"questionTotal"}, totalMarks: 5,
    rows: [
    { id: "r-1", kind: "point", verbatim: "1. Compares 28 to the value in mid (18). It is greater so subarray to the left is dismissed.", marks: null },
    { id: "r-2", kind: "point", verbatim: "Now left is = 28, mid = 41, right = 50 (Note: mid may also be 35 depending on code", marks: null },
    { id: "r-3", kind: "point", verbatim: "implementation – do not deduct marks)", marks: null },
    { id: "r-4", kind: "point", verbatim: "2. Compares 28 to the value in mid(41 or 35). It is smaller so subarray to the right is", marks: null },
    { id: "r-5", kind: "point", verbatim: "dismissed. Now left = 28, mid = 35, right = 41", marks: null },
    { id: "r-6", kind: "point", verbatim: "3. Compares 28 to the value in mid (35). It is smaller so subarray to the right is dismissed.", marks: null },
    { id: "r-7", kind: "point", verbatim: "Now left = 28, mid = 28, right =28. Returns index 4", marks: null },
    { id: "r-8", kind: "point", verbatim: "Similar explanations acceptable.", marks: null },
    { id: "r-9", kind: "point", verbatim: "Alternative", marks: null },
    { id: "r-10", kind: "point", verbatim: "28 > 18 => left <- (mid+1) = 4; mid <- (left+right)/2 = (4+7)/2 = 11/2 = 5", marks: null },
    { id: "r-11", kind: "point", verbatim: "28 < 35 => right <- (mid-1) = 4; mid <- (left+right)/2 = (4+4)/2 = 8/2 = 4", marks: null },
    { id: "r-12", kind: "point", verbatim: "28 = 28 => found", marks: null },
    ],
