    schemeCitation: "Marking points quoted from the SEC marking scheme, Computer Science 2021 Higher Level — © State Examinations Commission.",
    id: "cs-2021-hl-q11-a", topicId: "cs-2-2", conceptId: "two-benefits-computer-modelling",
    section: "A", questionRef: "2021 HL Q11(a)",
    questionText: "State two benefits of computer modelling.",
    tariffModel: {"kind":"questionTotal"}, totalMarks: 2,
