    section: "B", questionRef: "2024 HL Q15(c)(ii)",
    questionText: "Another stage in a typical analytics project is data cleaning. Name and describe two types of data errors that can be removed using data cleaning.",
    tariffModel: {"kind":"questionTotal"}, totalMarks: 6,
    rows: [
    { id: "r-1", kind: "point", verbatim: "Any two from the following:", marks: null },
    { id: "r-2", kind: "point", verbatim: "Missing Values: Data entries that are incomplete or entirely absent can be filled in with appropriate values or removed if they are not critical.", marks: null },
    { id: "r-3", kind: "point", verbatim: "Duplicate Records: Repeated entries that skew analysis and statistics can be identified and eliminated to ensure each data point is unique.", marks: null },
    { id: "r-4", kind: "point", verbatim: "Inconsistent Formatting: Variations in data formatting (e.g. date formats, capitalisation, unit measurements) can be standardised for consistency.", marks: null },
    { id: "r-5", kind: "point", verbatim: "Outliers and Anomalies: Data points that deviate significantly from the norm can be investigated and corrected or removed if they are erroneous.", marks: null },
    { id: "r-6", kind: "point", verbatim: "Incorrect Data Types: Values that are in the wrong format or type (e.g. text in a numerical field) can be converted to the correct type or corrected as needed.", marks: null },
    { id: "r-7", kind: "point", verbatim: "Typographical Errors: Spelling mistakes, typographical errors, and other text inaccuracies can be corrected to ensure data consistency and accuracy.", marks: null },
    { id: "r-8", kind: "point", verbatim: "Inconsistent Categories: Categorical data that uses different labels for the same category (e.g. \"Y\" vs. \"Yes\") can be standardised to unify the categories.", marks: null },
    ],
